import React from 'react';

// Higher-Order Component pattern: wraps any remote's exposed module so
// one failing micro-frontend (a bad deploy, a runtime exception) can't
// take down the whole host shell. Class component because React has no
// hook equivalent for componentDidCatch/getDerivedStateFromError.
class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError() {
    return { hasError: true };
  }

  componentDidCatch(error, info) {
    console.error(`[${this.props.label || 'micro-frontend'}] failed to render`, error, info);
  }

  render() {
    if (this.state.hasError) {
      return (
        this.props.fallback || (
          <div className="nh-mfe-error">
            No se pudo cargar "{this.props.label || 'este módulo'}".
          </div>
        )
      );
    }
    return this.props.children;
  }
}

export function withErrorBoundary(Component, label) {
  return function Wrapped(props) {
    return (
      <ErrorBoundary label={label}>
        <Component {...props} />
      </ErrorBoundary>
    );
  };
}

export default ErrorBoundary;
